float remap(float val, float inMin, float inMax, float outMin, float outMax)
{
    return outMin + (val - inMin) * (outMax - outMin) / (inMax - inMin);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    float remappedX = remap(iMouse.x, 0., iResolution.x, 0., 1.);
    float clampedValue = clamp(uv.x, .3, .85);

    vec3 col = vec3(1.);
    vec3 white = vec3(1.);
    vec3 black = vec3(0.);
    vec3 blue = vec3(0.,0.,1.);
    vec3 red = vec3(1.,0.,0.);

    float linearLine = smoothstep(0., .01, abs(uv.y - clampedValue));

    col = mix(red, blue, min(clampedValue, uv.x));
    col = mix(white, col, linearLine);

    fragColor = vec4(col,1.0);
}
